import { statSync } from 'node:fs';
import { win32 } from 'node:path';
function isFile(path) {
    try {
        return statSync(path).isFile();
    }
    catch {
        return false;
    }
}
export function currentHost() {
    return { platform: process.platform, execPath: process.execPath, env: process.env, isFile };
}
const EXEC_PATH_ENTRY = {
    npm: /^npm-cli\.js$/i,
    pnpm: /^pnpm\.(c?js|mjs|exe)$/i,
};
const NPM_CLI = 'node_modules/npm/bin/npm-cli.js';
const SHIM_TARGETS = {
    npm: [NPM_CLI],
    pnpm: [
        'node_modules/pnpm/pnpm.exe',
        'node_modules/@pnpm/exe/pnpm.exe',
        'node_modules/pnpm/bin/pnpm.cjs',
        'node_modules/pnpm/bin/pnpm.mjs',
        'node_modules/corepack/dist/pnpm.js',
    ],
};
function shimRoot(dir) {
    const parent = win32.dirname(dir);
    const inBin = win32.basename(dir).toLowerCase() === '.bin' &&
        win32.basename(parent).toLowerCase() === 'node_modules';
    return inBin ? win32.dirname(parent) : dir;
}
function envValue(env, name) {
    const key = Object.keys(env).find((k) => k.toUpperCase() === name.toUpperCase());
    return key === undefined ? undefined : env[key];
}
function entryCommand(host, entry) {
    return /\.exe$/i.test(entry)
        ? { ok: true, command: entry, args: [] }
        : { ok: true, command: host.execPath, args: [entry] };
}
function resolveOnWindows(pm, host) {
    const execPathEntry = envValue(host.env, 'npm_execpath');
    if (execPathEntry &&
        win32.isAbsolute(execPathEntry) &&
        EXEC_PATH_ENTRY[pm].test(win32.basename(execPathEntry)) &&
        host.isFile(execPathEntry)) {
        return entryCommand(host, execPathEntry);
    }
    const dirs = (envValue(host.env, 'PATH') ?? '')
        .split(';')
        .map((dir) => dir.trim().replace(/^"(.*)"$/, '$1'))
        .filter((dir) => dir && win32.isAbsolute(dir));
    for (const dir of dirs) {
        const exe = win32.join(dir, `${pm}.exe`);
        if (host.isFile(exe))
            return { ok: true, command: exe, args: [] };
        if (!host.isFile(win32.join(dir, `${pm}.cmd`)))
            continue;
        const root = shimRoot(dir);
        for (const target of SHIM_TARGETS[pm]) {
            const entry = win32.join(root, target);
            if (host.isFile(entry))
                return entryCommand(host, entry);
        }
    }
    if (pm === 'npm') {
        const bundled = win32.join(win32.dirname(host.execPath), NPM_CLI);
        if (host.isFile(bundled))
            return entryCommand(host, bundled);
        return {
            ok: false,
            message: `Could not find npm. On Windows npm runs as node npm-cli.js, without a shell, and no npm-cli.js was found from PATH or next to ${host.execPath}.`,
        };
    }
    return {
        ok: false,
        message: 'Could not find pnpm. On Windows pnpm runs without a shell, so it needs pnpm.exe on PATH or a pnpm.cmd from npm, Corepack or node_modules/.bin next to its pnpm.exe, pnpm.cjs or pnpm.mjs.',
    };
}
export function resolvePackageManager(pm, host = currentHost()) {
    if (host.platform !== 'win32')
        return { ok: true, command: pm, args: [] };
    return resolveOnWindows(pm, host);
}
